import { textAss } from './overlays';
import { outputCues, serializeSrt } from './subtitles';
import type { EditSettings, MediaAsset } from './types';
export interface RecipeResources { captions: string; fonts: string; text: string; image: string }
export const resourcePaths = (prefix = 'frame'): RecipeResources => ({ captions: `${prefix}-captions.srt`, fonts: 'fonts', text: `${prefix}-text.ass`, image: `${prefix}-image.png` });
/** Paths are generated by the engine, never supplied by project documents. */
export const filterPath = (path: string) => `'${path.replace(/\\/g, '/').replace(/:/g, '\\:').replace(/'/g, "'\\''")}'`;
export function recipeFiles(edit: EditSettings, paths: RecipeResources, asset?: MediaAsset): { path: string; text: string }[] {
  const files = edit.subtitles.mode !== 'none' && outputCues(edit).length ? [{ path: paths.captions, text: serializeSrt(outputCues(edit)) }] : [];
  if (edit.overlays.text) files.push({ path: paths.text, text: textAss(edit, asset) });
  return files;
}
